237	  border: 1px solid var(--border);
238	}
239	
240	.btn-secondary:hover {
241	  background: var(--border);
242	}
243	
244	.btn-group {
245	  display: flex;
246	  gap: 0.75rem;
247	  flex-wrap: wrap;
248	}
249	
250	/* Output Panel */
251	.output-panel {
252	  background: var(--code-bg);
253	  border: 1px solid var(--border);
254	  border-radius: 8px;
255	  padding: 1rem;
256	  min-height: 300px;
