271	
272	.output-line {
273	  margin-bottom: 0.5rem;
274	}
275	
276	.output-line.error {
277	  color: var(--error);
278	}
279	
280	.output-line.success {
281	  color: var(--success);
282	}
283	
284	/* Notebook List */
285	.notebook-list {
286	  display: flex;
287	  flex-direction: column;
288	  gap: 0.5rem;
289	}
290	
291	.notebook-item {
292	  padding: 1rem;
293	  background: var(--surface-hover);
294	  border: 1px solid var(--border);
295	  border-radius: 8px;
