299	
300	.notebook-item:hover {
301	  border-color: var(--accent);
302	  background: var(--accent-surface);
303	}
304	
305	.notebook-item.active {
306	  border-color: var(--accent);
307	  background: var(--accent-surface);
308	}
309	
310	.notebook-name {
311	  font-weight: 500;
312	  margin-bottom: 0.25rem;
313	}
314	
315	.notebook-id {
316	  font-size: 0.75rem;
317	  color: var(--text-tertiary);
318	  font-family: 'Courier New', monospace;
319	}
320	
321	/* Instructions */
322	.instructions {
323	  background: var(--accent-surface);
324	  border: 1px solid var(--accent);
325	  border-radius: 8px;
326	  padding: 1rem;
327	  margin-bottom: 1.5rem;
328	}
329	
330	.instructions h3 {
331	  font-size: 0.875rem;
332	  font-weight: 600;
333	  margin-bottom: 0.75rem;
334	}
335	
336	.instructions ol {
337	  padding-left: 1.25rem;
338	  font-size: 0.875rem;
339	  line-height: 1.6;
340	}
341	
342	.instructions li {
343	  margin-bottom: 0.5rem;
344	}
345	
346	.instructions code {
347	  background: var(--code-bg);
348	  padding: 0.125rem 0.375rem;
349	  border-radius: 4px;
350	  font-size: 0.8125rem;
351	  font-family: 'Courier New', monospace;
352	}
353	
354	/* Alert */
355	.alert {
356	  padding: 1rem;
357	  border-radius: 8px;
358	  margin-bottom: 1rem;
359	  font-size: 0.875rem;
360	}
361	
362	.alert.warning {
363	  background: var(--error-surface);
364	  border: 1px solid var(--error);
365	  color: var(--text);
366	}
367	
368	.alert.info {
