426	
427	  <div class="layout">
428	    <!-- Sidebar: Connection & Settings -->
429	    <aside>
430	      <div class="card">
431	        <div class="card-header">Notebook Selection</div>
432	        <div class="notebook-list">
433	          <div class="notebook-item active" data-id="1iYIe9pNcGO3nFYX2BOVtrLCJoF37PzP6">
434	            <div class="notebook-name">AI Tools Notebook</div>
435	            <div class="notebook-id">1iYIe9pNcGO3nFYX2BOVtrLCJoF37PzP6</div>
