503	<script>
504	// State management
505	const state = {
506	  connected: false,
507	  notebookId: '',
508	  serviceAccount: null,
509	  executing: false
510	};
511	
512	// Load saved configuration
513	function loadConfig() {
514	  try {
515	    const saved = localStorage.getItem('colab_config');
516	    if (saved) {
517	      const config = JSON.parse(saved);
518	      if (config.notebookId) {
519	        document.getElementById('notebookId').value = config.notebookId;
520	        state.notebookId = config.notebookId;
521	      }
522	      if (config.serviceAccount) {
523	        document.getElementById('serviceAccount').value = config.serviceAccount;
524	      }
525	    }
526	  } catch (e) {
527	    console.warn('Could not load saved config:', e);
528	  }
529	}
530	
531	// Save configuration
532	function saveConfig() {
533	  try {
534	    const config = {
535	      notebookId: document.getElementById('notebookId').value,
536	      serviceAccount: document.getElementById('serviceAccount').value
537	    };
538	    localStorage.setItem('colab_config', JSON.stringify(config));
539	  } catch (e) {
540	    console.warn('Could not save config:', e);
541	  }
542	}
543	
544	// Update UI connection state
545	function updateConnectionState(connected, message) {
546	  state.connected = connected;
547	  const statusDot = document.getElementById('statusDot');
548	  const statusText = document.getElementById('statusText');
549	  const warning = document.getElementById('connectionWarning');
550	  const runBtn = document.getElementById('runBtn');
551	
552	  if (connected) {
553	    statusDot.classList.add('connected');
554	    statusText.textContent = message || 'Connected';
555	    warning.style.display = 'none';
556	    runBtn.disabled = false;
557	  } else {
558	    statusDot.classList.remove('connected');
559	    statusText.textContent = message || 'Not Connected';
560	    warning.style.display = 'block';
561	    runBtn.disabled = true;
562	  }
563	}
564	
565	// Connect to Colab
566	function connect() {
567	  const notebookId = document.getElementById('notebookId').value.trim();
568	  const serviceAccountText = document.getElementById('serviceAccount').value.trim();
569	
570	  if (!notebookId) {
571	    addOutput('❌ Please enter a Notebook ID', 'error');
572	    return;
573	  }
574	
575	  if (!serviceAccountText) {
576	    addOutput('⚠️ No service account provided. Using demo mode.', 'error');
577	    updateConnectionState(true, `Demo Mode: ${notebookId.substring(0, 8)}...`);
578	    saveConfig();
579	    return;
580	  }
581	
582	  try {
583	    const serviceAccount = JSON.parse(serviceAccountText);
584	    state.serviceAccount = serviceAccount;
585	    state.notebookId = notebookId;
586	
587	    updateConnectionState(true, `Connected: ${notebookId.substring(0, 8)}...`);
588	    addOutput(`✅ Connected to notebook: ${notebookId}`, 'success');
589	    addOutput(`📧 Service account: ${serviceAccount.client_email || 'N/A'}`, 'success');
590	    saveConfig();
591	  } catch (e) {
592	    addOutput(`❌ Invalid JSON: ${e.message}`, 'error');
593	  }
594	}
595	
596	// Clear authentication
597	function clearAuth() {
598	  document.getElementById('serviceAccount').value = '';
599	  document.getElementById('notebookId').value = '1iYIe9pNcGO3nFYX2BOVtrLCJoF37PzP6';
600	  updateConnectionState(false);
601	  try {
602	    localStorage.removeItem('colab_config');
603	  } catch (e) {}
604	  addOutput('🔒 Authentication cleared', 'success');
605	}
606	
607	// Execute code
608	async function executeCode() {
609	  if (!state.connected || state.executing) return;
610	
611	  const code = document.getElementById('codeInput').value.trim();
612	  if (!code) {
613	    addOutput('❌ Please enter code to execute', 'error');
614	    return;
615	  }
616	
617	  state.executing = true;
618	  const runBtn = document.getElementById('runBtn');
619	  const runIcon = document.getElementById('runIcon');
620	  const runText = document.getElementById('runText');
621	
622	  runBtn.disabled = true;
623	  runIcon.innerHTML = '<span class="spinner"></span>';
624	  runText.textContent = 'Executing...';
625	
626	  addOutput(`\n▶️ Executing code...`, 'success');
627	  addOutput(`\`\`\`python\n${code}\n\`\`\``);
628	
629	  // Simulate execution (replace with real backend API call)
630	  await simulateExecution(code);
631	
632	  state.executing = false;
633	  runBtn.disabled = false;
634	  runIcon.textContent = '▶️';
635	  runText.textContent = 'Run Code';
636	}
637	
638	// Simulate code execution (demo mode)
639	async function simulateExecution(code) {
640	  await new Promise(resolve => setTimeout(resolve, 1500));
641	
642	  addOutput('\n📊 Output:');
643	
644	  if (code.includes('import') || code.includes('print')) {
645	    addOutput('Note: This is demo mode. Real execution requires backend integration.', 'error');
646	    addOutput('\nTo enable real execution:');
647	    addOutput('1. Deploy the FastAPI backend (see README.md)');
648	    addOutput('2. Configure Google Cloud service account');
649	    addOutput('3. Grant notebook access to the service account');
650	  }
651	
652	  addOutput('\n✅ Execution complete (demo mode)');
653	}
654	
655	// Add output line
656	function addOutput(text, type = '') {
657	  const panel = document.getElementById('outputPanel');
658	  const line = document.createElement('div');
659	  line.className = 'output-line ' + type;
660	  line.textContent = text;
661	  panel.appendChild(line);
662	  panel.scrollTop = panel.scrollHeight;
663	}
664	
665	// Clear output
666	function clearOutput() {
667	  document.getElementById('outputPanel').innerHTML = '';
668	}
669	
670	// Notebook item selection
671	document.querySelectorAll('.notebook-item').forEach(item => {
672	  item.addEventListener('click', () => {
673	    document.querySelectorAll('.notebook-item').forEach(i => i.classList.remove('active'));
674	    item.classList.add('active');
675	    document.getElementById('notebookId').value = item.dataset.id;
676	  });
677	});
678	
679	// Initialize
680	loadConfig();
681	</script>

