504	// State management
505	const state = {
506	  connected: false,
507	  notebookId: '',
508	  serviceAccount: null,
509	  executing: false
510	};
511	
512	// Load saved configuration
513	function loadConfig() {
514	  try {
515	    const saved = localStorage.getItem('colab_config');
516	    if (saved) {
517	      const config = JSON.parse(saved);
518	      if (config.notebookId) {
519	        document.getElementById('notebookId').value = config.notebookId;
520	        state.notebookId = config.notebookId;
521	      }
522	      if (config.serviceAccount) {
523	        document.getElementById('serviceAccount').value = config.serviceAccount;
524	      }
525	    }
526	  } catch (e) {
527	    console.warn('Could not load saved config:', e);
528	  }
529	}
530	
531	// Save configuration
532	function saveConfig() {
533	  try {
534	    const config = {
535	      notebookId: document.getElementById('notebookId').value,
536	      serviceAccount: document.getElementById('serviceAccount').value
537	    };
538	    localStorage.setItem('colab_config', JSON.stringify(config));
539	  } catch (e) {
540	    console.warn('Could not save config:', e);
541	  }
542	}
543	
544	// Update UI connection state
545	function updateConnectionState(connected, message) {
546	  state.connected = connected;
547	  const statusDot = document.getElementById('statusDot');
548	  const statusText = document.getElementById('statusText');
549	  const warning = document.getElementById('connectionWarning');
550	  const runBtn = document.getElementById('runBtn');
551	
552	  if (connected) {
553	    statusDot.classList.add('connected');
554	    statusText.textContent = message || 'Connected';
555	    warning.style.display = 'none';
556	    runBtn.disabled = false;
557	  } else {
558	    statusDot.classList.remove('connected');
559	    statusText.textContent = message || 'Not Connected';
560	    warning.style.display = 'block';
561	    runBtn.disabled = true;
562	  }
563	}
564	
565	// Connect to Colab
566	function connect() {
567	  const notebookId = document.getElementById('notebookId').value.trim();
568	  const serviceAccountText = document.getElementById('serviceAccount').value.trim();
569	
570	  if (!notebookId) {
571	    addOutput('❌ Please enter a Notebook ID', 'error');
572	    return;
573	  }
574	
575	  if (!serviceAccountText) {
576	    addOutput('⚠️ No service account provided. Using demo mode.', 'error');
577	    updateConnectionState(true, `Demo Mode: ${notebookId.substring(0, 8)}...`);
578	    saveConfig();
579	    return;
580	  }
581	
582	  try {
583	    const serviceAccount = JSON.parse(serviceAccountText);
584	    state.serviceAccount = serviceAccount;
585	    state.notebookId = notebookId;
586	
587	    updateConnectionState(true, `Connected: ${notebookId.substring(0, 8)}...`);
588	    addOutput(`✅ Connected to notebook: ${notebookId}`, 'success');
589	    addOutput(`📧 Service account: ${serviceAccount.client_email || 'N/A'}`, 'success');
590	    saveConfig();
591	  } catch (e) {
592	    addOutput(`❌ Invalid JSON: ${e.message}`, 'error');
593	  }
594	}
595	
596	// Clear authentication
597	function clearAuth() {
598	  document.getElementById('serviceAccount').value = '';
599	  document.getElementById('notebookId').value = '1iYIe9pNcGO3nFYX2BOVtrLCJoF37PzP6';
600	  updateConnectionState(false);
601	  try {
602	    localStorage.removeItem('colab_config');
603	  } catch (e) {}
604	  addOutput('🔒 Authentication cleared', 'success');
