def sanitize_folder_segment(name: str) -> str:
    """Sanitize folder name by stripping trailing whitespace and illegal Windows chars."""
    clean = name.strip().strip(".")
    for ch in '<>:"/\\|?*':
        clean = clean.replace(ch, "_")
    return clean.strip() or "Untitled"


def sanitize_rel_path(rel_path: str) -> str:
    """Sanitize multi-level relative folder path for Windows filesystem."""
    if not rel_path or rel_path == ".":
        return ""
    parts = [sanitize_folder_segment(p) for p in rel_path.replace("\\", "/").split("/") if p.strip()]
    return "/".join(parts)


def safe_cv2_write(file_path: Path, img_bgr) -> bool:
    """
    Safely write image using cv2.imencode + Python open().
    Supports Unicode paths, spaces, and validates file exists on disk.
    """
    file_path.parent.mkdir(parents=True, exist_ok=True)
    ext = file_path.suffix or ".png"
    success, buf = cv2.imencode(ext, img_bgr)
    if not success:
        raise RuntimeError(f"Failed to encode image to {ext}")
    with open(file_path, "wb") as f:
        f.write(buf.tobytes())
    if not file_path.exists() or file_path.stat().st_size == 0:
        raise RuntimeError(f"Verified disk write failed: {file_path}")
    return True


